P.append(dict(id=7, titre='Au clavier, chaque composant a un focus différent, ou celui du navigateur', grav='gêne', effort='1 h', axes='fonction · familiarité',
 symptome='Au clavier, le contrôle segmenté, le lien de la barre et le bouton principal prennent l’anneau noir du navigateur, collé au bord ; la ligne de commande prend un anneau bleu décalé ; Dicter, une bordure bleue épaissie ; le texte du message, un contour bleu à 1 px. Le contrôle segmenté ne réagit pas sous la souris : les segments non choisis ressemblent à du texte.',
 preuves=[('e10-focus-onglets-1440.webp', 'Contrôle segmenté, focus.'), ('e10-focus-installer-1440.webp', 'Bouton principal, focus.'), ('e10-focus-ligne-1440.webp', 'Ligne de commande, focus (le seul dessiné).'), ('e10-survol-onglets-1440.webp', 'Survol de « Réunions » : rien ne change.')],
 mesure='Inventaire : 13 composants sur 25 sans focus dessiné (<a href="inventaire.html#composants">Inventaire</a>). Quatre dessins de focus différents dans <code>style.css</code> (<code>:261</code>, <code>:363</code>, <code>:374</code>, et celui du navigateur). <code>.tabs button</code> : aucune règle <code>:hover</code>.',
 cause='Pas de règle <code>:focus-visible</code> générale ; chaque composant récent a reçu la sienne. <code>style.css:121</code> sans <code>:hover</code>.',
 impact='Toute personne qui navigue au clavier : 131 cibles à 1440 px. Le survol manquant touche chaque visiteur à la souris devant les onglets de l’accueil.',
 options=[('A. Un seul anneau : contour plein de 2 px à l’accent, décalé de 2 px ; segments non choisis plus clairs, qui foncent au survol', 'Ce que font Apple (2 px #0071E3), Notion (2 px, décalage 2) et Linear (1 px, décalage 2) ; une seule règle ; visible sur tous les fonds du site.', 'Les quatre dessins actuels sont à retirer ; les segments non choisis passent au gris secondaire.'),
          ('B. Garder le navigateur partout', 'Rien à écrire.', 'Noir, carré autour de formes arrondies, différent d’un navigateur à l’autre.'),
          ('C. Une bordure épaissie par composant', 'Discret.', 'Ce que fait Dicter aujourd’hui ; peu visible (1 px de plus).')],
 choix=0, argument='A est la convention observée et répond à WCAG 2.4.7 (2.4.13 au niveau AAA). Pour le survol, les sites observés ne changent pas le fond d’un onglet non choisi, seulement la couleur de son texte (Apple : #6E6E73 → #424245 ; Raycast : gris → blanc) ; le fond reste le signe du choix. Le prototype fait de même.',
 regles=[a(HIG + 'focus-and-selection', 'Apple HIG, Focus and selection') + ' : l’anneau de focus de macOS, à la couleur d’accent.', a(W21 + 'focus-visible', 'WCAG 2.4.7 Focus Visible') + ' ; ' + a(W22 + 'focus-appearance', '2.4.13 Focus Appearance') + ' (AAA) : 2 px, 3:1.', a(HIG + 'segmented-controls', 'Apple HIG, Segmented controls') + '.'],
 refq=[2, 3],
 spec=[('style.css, en tête', '—', ':focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }'),
       ('style.css:261, 363, 374', 'trois anneaux particuliers', 'remplacés par la règle commune'),
       ('style.css:121', '.tabs button { color: var(--text); }', '.tabs button { color: var(--secondary); transition: color .12s ease-out; } .tabs button[aria-selected="true"], .tabs button:hover { color: var(--text); }')],
 criteres=['Chaque élément focalisable des cinq pages montre le même anneau (vérifié sur la planche <a href="prototypes/etats.html">États</a>).', 'L’anneau a un contraste ≥ 3:1 avec le fond adjacent (accent sur <code>#edf2f8</code> : 4,97:1).', 'Un segment non choisi est en gris secondaire et passe à la couleur du texte au survol ; son fond ne change pas.'],
 proto='accueil', tranche=''))

